SELECT Categorias.Nombre, COUNT(*), AVG(Precio) FROM Productos INNER JOIN Categorias ON Productos.IdCategoria = Categorias.IdCategoria GROUP BY Categorias.Nombre
SELECT Categorias.Nombre, SUM(Precio*Cantidad) FROM Productos INNER JOIN Categorias ON Productos.IdCategoria = Categorias.IdCategoria INNER JOIN Ventas ON Ventas.IdProducto = Productos.IdProducto GROUP BY Categorias.Nombre HAVING SUM(Precio*Cantidad) > 100 ORDER BY SUM(Precio*Cantidad) DESC
SELECT Clientes.NombreCompleto, COUNT(*) FROM Clientes INNER JOIN Ventas ON Ventas.IdCliente = Clientes.IdCliente GROUP BY Clientes.NombreCompleto, Ventas.IdCliente ORDER BY COUNT(*) DESC
SELECT Departamentos.Nombre, AVG(Sueldo) FROM Departamentos JOIN Empleados ON Empleados.IdDepartamento = Departamentos.IdDepartamento GROUP BY Departamentos.Nombre, Empleados.IdEmpleado HAVING AVG(Sueldo) < 100000 ORDER BY AVG(Sueldo) DESC
SELECT Productos.Nombre, AVG(Precio*Cantidad) FROM Productos INNER JOIN Ventas ON Ventas.IdProducto = Productos.IdProducto GROUP BY Productos.Nombre, Ventas.IdVenta HAVING AVG(Precio*Cantidad) > 50 ORDER BY AVG(Precio*Cantidad) DESC
SELECT Clientes.NombreCompleto, AVG(Precio*Cantidad) FROM Clientes INNER JOIN Ventas ON Clientes.IdCliente = Ventas.IdCliente INNER JOIN Productos ON Productos.IdProducto = Ventas.IdProducto GROUP BY Clientes.NombreCompleto 
SELECT Categorias.Nombre, MIN(Precio*Cantidad) FROM Categorias INNER JOIN Productos ON Categorias.IdCategoria = Productos.IdCategoria INNER JOIN Ventas ON Ventas.IdProducto = Productos.IdProducto GROUP BY Categorias.Nombre HAVING MIN(Precio*Cantidad) < 200 AND MIN(Precio*Cantidad) > 0 ORDER BY MIN(Precio*Cantidad) ASC
SELECT Clientes.NombreCompleto, Productos.Nombre, SUM(Cantidad) AS Total FROM Ventas INNER JOIN Clientes ON Clientes.IdCliente = Ventas.IdCliente INNER JOIN Productos ON Productos.IdProducto = Ventas.IdProducto GROUP BY Clientes.NombreCompleto, Productos.Nombre 